-- The record of the auth store's steps.
create table if not exists "auth_steps" (
  "module" text not null,
  "step" integer not null,
  "target" text not null,
  "applied_at" timestamptz,
  primary key ("module", "step", "target")
);

-- auth 1 core: Better Auth's users, sessions, accounts, verifications and signing keys.
create table if not exists "user" (id text primary key);

alter table "user"
  add column if not exists "name" text not null,
  add column if not exists "email" text not null unique,
  add column if not exists "email_verified" boolean not null,
  add column if not exists "image" text,
  add column if not exists "created_at" timestamptz default current_timestamp not null,
  add column if not exists "updated_at" timestamptz default current_timestamp not null,
  add column if not exists "role" text,
  add column if not exists "banned" boolean,
  add column if not exists "ban_reason" text,
  add column if not exists "ban_expires" timestamptz,
  add column if not exists "last_role" text,
  add column if not exists "email_confirmed_at" timestamptz;

create table "session" (
  id text primary key,
  "expires_at" timestamptz not null,
  "token" text not null unique,
  "created_at" timestamptz default current_timestamp not null,
  "updated_at" timestamptz not null,
  "ip_address" text,
  "user_agent" text,
  "user_id" text not null references "user" (id) on delete cascade,
  "impersonated_by" text,
  "active_role" text
);

create index "session_user_id_idx" on "session" ("user_id");

create table "account" (
  id text primary key,
  "account_id" text not null,
  "provider_id" text not null,
  "user_id" text not null references "user" (id) on delete cascade,
  "access_token" text,
  "refresh_token" text,
  "id_token" text,
  "access_token_expires_at" timestamptz,
  "refresh_token_expires_at" timestamptz,
  "scope" text,
  "password" text,
  "created_at" timestamptz default current_timestamp not null,
  "updated_at" timestamptz not null
);

create index "account_user_id_idx" on "account" ("user_id");

create table "verification" (
  id text primary key,
  "identifier" text not null,
  "value" text not null,
  "expires_at" timestamptz not null,
  "created_at" timestamptz default current_timestamp not null,
  "updated_at" timestamptz default current_timestamp not null
);

create index "verification_identifier_idx" on "verification" ("identifier");

create table "jwks" (
  id text primary key,
  "public_key" text not null,
  "private_key" text not null,
  "created_at" timestamptz not null,
  "expires_at" timestamptz,
  "alg" text,
  "crv" text
);

insert into "auth_steps" ("module", "step", "target", "applied_at") values ('auth', 1, 'auth', now());

-- auth 2 account_keys: One account per provider and account id, and per person where a provider links one.
do $check$
declare
  found text;
begin
  select string_agg(format('%s %s (accounts %s)', provider, subject, ids), '; ') into found
  from (
    select "provider_id" as provider, "account_id" as subject, string_agg(id::text, ', ' order by id) as ids
    from "account" group by "provider_id", "account_id" having count(*) > 1 order by 1, 2 limit 20
  ) as twice;
  if found is not null then
    raise exception 'The auth store has more than one account for a provider and account id: %. Keep one of each in a migration of the project''s own written before this one, then apply again.', found;
  end if;
end
$check$;

create unique index "account_provider_id_account_id_uidx" on "account" ("provider_id", "account_id");

alter table "account" add column "single_subject_user_id" text;

create unique index "account_provider_id_single_subject_user_id_uidx" on "account" ("provider_id", "single_subject_user_id");

insert into "auth_steps" ("module", "step", "target", "applied_at") values ('auth', 2, 'auth', now());

-- auth 3 user_indexes: The indexes that find the active admins and page through the users.
create index if not exists "user_active_admin_idx" on "user" (id) where "banned" is not true and 'admin' = any(regexp_split_to_array(regexp_replace(regexp_replace(coalesce("role", 'user'), '^\s*\{(.*)\}\s*$', '\1'), '^\s*"?|"?\s*$', '', 'g'), '"?\s*,\s*"?'));

create index if not exists "user_created_at_id_idx" on "user" ("created_at", id);

insert into "auth_steps" ("module", "step", "target", "applied_at") values ('auth', 3, 'auth', now());

-- auth 4 verification_pattern_index: The index that finds app invitations.
create index "verification_identifier_pattern_idx" on "verification" ("identifier" text_pattern_ops);

insert into "auth_steps" ("module", "step", "target", "applied_at") values ('auth', 4, 'auth', now());

-- auth 5 user_name_search: The indexes that find the users by a part of their name and list them by name.
create extension if not exists pg_trgm;

create index if not exists "user_name_id_idx" on "user" ("name", id);

create index if not exists "user_name_trgm_idx" on "user" using gin ("name" gin_trgm_ops);

insert into "auth_steps" ("module", "step", "target", "applied_at") values ('auth', 5, 'auth', now());

-- two_factor 1 two_factor: The authenticator secrets and backup codes of two-step sign-in.
create table "two_factor" (
  id text primary key,
  "secret" text not null,
  "backup_codes" text not null,
  "user_id" text not null references "user" (id) on delete cascade,
  "verified" boolean,
  "failed_verification_count" integer,
  "locked_until" timestamptz
);

create index "two_factor_secret_idx" on "two_factor" ("secret");

create index "two_factor_user_id_idx" on "two_factor" ("user_id");

insert into "auth_steps" ("module", "step", "target", "applied_at") values ('two_factor', 1, 'two_factor', now());

-- two_factor 1 two_factor, on the tables of auth: The authenticator secrets and backup codes of two-step sign-in.
alter table "user" add column if not exists "two_factor_enabled" boolean;

insert into "auth_steps" ("module", "step", "target", "applied_at") values ('two_factor', 1, 'auth', now());

-- passkeys 1 passkeys: The users' passkeys.
create table "passkey" (
  id text primary key,
  "name" text,
  "public_key" text not null,
  "user_id" text not null references "user" (id) on delete cascade,
  "credential_id" text not null,
  "counter" integer not null,
  "device_type" text not null,
  "backed_up" boolean not null,
  "transports" text,
  "created_at" timestamptz,
  "aaguid" text,
  "rp_id" text
);

create index "passkey_user_id_idx" on "passkey" ("user_id");

create index "passkey_credential_id_idx" on "passkey" ("credential_id");

insert into "auth_steps" ("module", "step", "target", "applied_at") values ('passkeys', 1, 'passkeys', now());

-- passkeys 2 rp_id_index: The index that finds passkeys by RP ID.
create index "passkey_rp_id_idx" on "passkey" ("rp_id");

insert into "auth_steps" ("module", "step", "target", "applied_at") values ('passkeys', 2, 'passkeys', now());

-- sign_in_policy 1 sign_in_policy: The sign-in policies admins saved.
create table "sign_in_policy" (
  id text primary key,
  "password" text not null,
  "email_code" text not null,
  "passkey" text not null,
  "two_factor" text not null,
  "staff_access" text not null,
  "platform_sign_in" text not null,
  "created_at" timestamptz not null,
  "created_by" text
);

insert into "auth_steps" ("module", "step", "target", "applied_at") values ('sign_in_policy', 1, 'sign_in_policy', now());

-- staff_sign_in 1 staff_sign_in: The log of staff sign-ins as the app's people.
create table "staff_sign_in" (
  id text primary key,
  "user_id" text not null,
  "user_email" text not null,
  "staff" text not null,
  "staff_name" text,
  "staff_subject" text not null,
  "issuer" text not null,
  "reason" text not null,
  "session_id" text not null,
  "started_at" timestamptz not null,
  "expires_at" timestamptz not null,
  "ended_at" timestamptz
);

insert into "auth_steps" ("module", "step", "target", "applied_at") values ('staff_sign_in', 1, 'staff_sign_in', now());

-- staff_sign_in 2 staff_sign_in_indexes: The indexes that find staff sign-ins.
create index "staff_sign_in_session_id_idx" on "staff_sign_in" ("session_id");

create index "staff_sign_in_started_at_idx" on "staff_sign_in" ("started_at" desc);

insert into "auth_steps" ("module", "step", "target", "applied_at") values ('staff_sign_in', 2, 'staff_sign_in', now());

-- platform_devices 1 platform_devices: The device accounts people signed out of, and the sessions of each device.
create table "refused_account" (
  id text primary key,
  "provider_id" text not null,
  "account_id" text not null,
  "user_id" text not null references "user" (id) on delete cascade,
  "created_at" timestamptz not null,
  unique ("provider_id", "account_id")
);

create index "refused_account_user_id_idx" on "refused_account" ("user_id");

create table "device_session" (
  id text primary key,
  "session_id" text not null unique references "session" (id) on delete cascade,
  "account_id" text not null,
  "created_at" timestamptz not null
);

create index "device_session_account_id_idx" on "device_session" ("account_id");

insert into "auth_steps" ("module", "step", "target", "applied_at") values ('platform_devices', 1, 'platform_devices', now());
